/**
 *
 * DataTableTHeadCell is a component that displays a thead cell inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableTHeadCell
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableTHeadCell component.
 */
export type DataTableTHeadCellPassThroughType<E> = PassThroughType<DataTableTHeadCellInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableTHeadCell component.
 */
export interface DataTableTHeadCellPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableTHeadCellPassThroughType<React.HTMLAttributes<HTMLTableCellElement>>;
}
/**
 * Defines valid properties in DataTableTHeadCell component.
 */
export interface DataTableTHeadCellProps extends BaseComponentProps<DataTableTHeadCellInstance, unknown, DataTableTHeadCellPassThrough, 'th'> {
    /**
     * Number of columns a header cell should span.
     * @default undefined
     */
    colSpan?: number | undefined;
    /**
     * Number of rows a header cell should span.
     * @default undefined
     */
    rowSpan?: number | undefined;
    /**
     * Whether the column is frozen.
     * @default false
     */
    frozen?: boolean | undefined;
    /**
     * Position of the frozen column, valid values are "left" and "right".
     * @default 'left'
     */
    alignFrozen?: 'left' | 'right' | undefined;
    /**
     * Defines the scope of the header cell.
     * @default 'col'
     */
    scope?: 'col' | 'colgroup' | 'row' | 'rowgroup' | undefined;
}
/**
 * Defines valid state in DataTableTHeadCell component.
 */
export interface DataTableTHeadCellState {
    /**
     * Whether the column is frozen.
     */
    frozen: boolean | undefined;
    /**
     * Whether the column is currently sorted, reported by a descendant DataTable.Sort.
     */
    isSorted: boolean;
}
/**
 * Defines the methods and properties exposed by DataTableTHeadCell component.
 */
export interface DataTableTHeadCellExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableTHeadCell component.
 */
export type DataTableTHeadCellInstance = ComponentInstance<DataTableTHeadCellProps, DataTableTHeadCellState, DataTableTHeadCellExposes>;
